[
  {
    "version": "v0.9",
    "createSurface": {
      "surfaceId": "tokyo_weather_photo_session",
      "catalogId": "https://genui.local/specification/v0_9/standard_catalog.json"
    }
  },
  {
    "version": "v0.9",
    "updateDataModel": {
      "surfaceId": "tokyo_weather_photo_session",
      "value": {
        "weatherData": [
          {
            "date": "June 10",
            "temp": "28°C",
            "humidity": "80%",
            "conditions": "Heavy Rain",
            "icon": "/icons/heavy_rain.png"
          },
          {
            "date": "June 11",
            "temp": "26°C",
            "humidity": "75%",
            "conditions": "Light Showers",
            "icon": "/icons/light_showers.png"
          },
          {
            "date": "June 12",
            "temp": "24°C",
            "humidity": "60%",
            "conditions": "Partly Cloudy",
            "icon": "/icons/partly_cloudy.png"
          }
        ]
      }
    }
  },
  {
    "version": "v0.9",
    "updateComponents": {
      "surfaceId": "tokyo_weather_photo_session",
      "components": [
        {
          "id": "root",
          "type": "Column",
          "spacing": "medium",
          "children": [
            "summary_text",
            "suitable_day_card",
            "analysis_card",
            "actions_card",
            "verification_card"
          ]
        },
        {
          "id": "summary_text",
          "type": "Text",
          "text": "Based on the provided weather data, **June 12th** is the most suitable day for an outdoor photography session in Tokyo due to partly cloudy conditions, lower temperature, and significantly lower humidity."
        },
        {
          "id": "suitable_day_card",
          "type": "Card",
          "children": [
            {
              "id": "suitable_day_column",
              "type": "Column",
              "spacing": "small",
              "children": [
                {
                  "id": "suitable_day_title",
                  "type": "Text",
                  "text": "Most Suitable Day: June 12th",
                  "style": "heading"
                },
                {
                  "id": "suitable_day_summary_row",
                  "type": "Row",
                  "spacing": "medium",
                  "verticalAlignment": "center",
                  "children": [
                    {
                      "id": "june12_icon",
                      "type": "Image",
                      "src": "/icons/partly_cloudy.png",
                      "alt": "Partly Cloudy"
                    },
                    {
                      "id": "june12_temp_row",
                      "type": "Row",
                      "spacing": "small",
                      "verticalAlignment": "center",
                      "children": [
                        {
                          "id": "june12_temp_icon",
                          "type": "Image",
                          "src": "/icons/temperature.png",
                          "alt": "Temperature"
                        },
                        {
                          "id": "june12_temp_text",
                          "type": "Text",
                          "text": "24°C"
                        }
                      ]
                    },
                    {
                      "id": "june12_humidity_row",
                      "type": "Row",
                      "spacing": "small",
                      "verticalAlignment": "center",
                      "children": [
                        {
                          "id": "june12_humidity_icon",
                          "type": "Image",
                          "src": "/icons/humidity.png",
                          "alt": "Humidity"
                        },
                        {
                          "id": "june12_humidity_text",
                          "type": "Text",
                          "text": "60%"
                        }
                      ]
                    }
                  ]
                },
                {
                  "id": "suitable_day_details",
                  "type": "Text",
                  "text": "These conditions are ideal for outdoor photography as the partly cloudy sky provides natural diffused light, reducing harsh shadows and glare, while the lower humidity and lack of precipitation ensure comfort and safety for equipment."
                }
              ]
            }
          ]
        },
        {
          "id": "analysis_card",
          "type": "Card",
          "children": [
            {
              "id": "analysis_column",
              "type": "Column",
              "spacing": "medium",
              "children": [
                {
                  "id": "analysis_title",
                  "type": "Text",
                  "text": "Weather Analysis",
                  "style": "heading"
                },
                {
                  "id": "weather_table_header",
                  "type": "Row",
                  "children": [
                    {
                      "id": "header_date",
                      "type": "Text",
                      "text": "**Date**",
                      "layout": {
                        "weight": 2
                      }
                    },
                    {
                      "id": "header_temp",
                      "type": "Text",
                      "text": "**Temp**",
                      "layout": {
                        "weight": 1
                      }
                    },
                    {
                      "id": "header_humidity",
                      "type": "Text",
                      "text": "**Humidity**",
                      "layout": {
                        "weight": 1
                      }
                    },
                    {
                      "id": "header_conditions",
                      "type": "Text",
                      "text": "**Conditions**",
                      "layout": {
                        "weight": 2
                      }
                    }
                  ]
                },
                {
                  "id": "weather_list",
                  "type": "List",
                  "binding": {
                    "data": "weatherData"
                  },
                  "itemTemplate": {
                    "id": "weather_row_template",
                    "type": "Row",
                    "verticalAlignment": "center",
                    "children": [
                      {
                        "id": "item_date",
                        "type": "Text",
                        "text": "{item.date}",
                        "layout": {
                          "weight": 2
                        }
                      },
                      {
                        "id": "item_temp",
                        "type": "Text",
                        "text": "{item.temp}",
                        "layout": {
                          "weight": 1
                        }
                      },
                      {
                        "id": "item_humidity",
                        "type": "Text",
                        "text": "{item.humidity}",
                        "layout": {
                          "weight": 1
                        }
                      },
                      {
                        "id": "item_conditions_row",
                        "type": "Row",
                        "spacing": "small",
                        "verticalAlignment": "center",
                        "layout": {
                          "weight": 2
                        },
                        "children": [
                          {
                            "id": "item_icon",
                            "type": "Image",
                            "src": "{item.icon}",
                            "alt": "{item.conditions}"
                          },
                          {
                            "id": "item_conditions_text",
                            "type": "Text",
                            "text": "{item.conditions}"
                          }
                        ]
                      }
                    ]
                  }
                }
              ]
            }
          ]
        },
        {
          "id": "actions_card",
          "type": "Card",
          "children": [
            {
              "id": "actions_column",
              "type": "Column",
              "spacing": "medium",
              "children": [
                {
                  "id": "actions_title",
                  "type": "Text",
                  "text": "Quick Actions",
                  "style": "heading"
                },
                {
                  "id": "actions_row",
                  "type": "Row",
                  "spacing": "medium",
                  "children": [
                    {
                      "id": "forecast_button",
                      "type": "Button",
                      "label": "Check Tokyo Weather Forecast",
                      "action": {
                        "functionCall": {
                          "call": "openUrl",
                          "args": [
                            "https://www.jma.go.jp/jma/indexe.html"
                          ]
                        }
                      }
                    },
                    {
                      "id": "tips_button",
                      "type": "Button",
                      "label": "Photography Tips for Cloudy Weather",
                      "action": {
                        "functionCall": {
                          "call": "openUrl",
                          "args": [
                            "https://example.com/photography_tips_cloudy.html"
                          ]
                        }
                      }
                    }
                  ]
                }
              ]
            }
          ]
        },
        {
          "id": "verification_card",
          "type": "Card",
          "children": [
            {
              "id": "verification_column",
              "type": "Column",
              "spacing": "medium",
              "children": [
                {
                  "id": "verification_title",
                  "type": "Text",
                  "text": "Steps to Verify Future Live Information",
                  "style": "heading"
                },
                {
                  "id": "verification_list",
                  "type": "List",
                  "numbered": true,
                  "children": [
                    {
                      "id": "step1",
                      "type": "Text",
                      "text": "**Visit a reliable weather website or app**: Use services like the Japan Meteorological Agency (JMA), AccuWeather, or The Weather Channel."
                    },
                    {
                      "id": "step2",
                      "type": "Text",
                      "text": "**Search for Tokyo**: Enter \"Tokyo, Japan\" into the search bar."
                    },
                    {
                      "id": "step3",
                      "type": "Text",
                      "text": "**Check the forecast**: Look for detailed hourly or daily forecasts, paying close attention to precipitation, cloud cover, temperature, and humidity for your desired dates and times."
                    },
                    {
                      "id": "step4",
                      "type": "Text",
                      "text": "**Review satellite/radar images**: For real-time conditions, radar maps can show current rain activity."
                    },
                    {
                      "id": "step5",
                      "type": "Text",
                      "text": "**Consider local webcams**: Some tourist areas or cities have live webcams that can give you a visual on current conditions."
                    }
                  ]
                }
              ]
            }
          ]
        }
      ]
    }
  }
]
